    }

    public func clean_non_binary_chars(): Unit {
        /*
        Clean the binary string by removing all non 0 or 1 characters.
        */
        var cleaned = ""
        for (bit in this.binary_string) {
            if (bit == '0' || bit == '1') {
                cleaned = cleaned + bit.toString()
            }
        }
        this.binary_string = cleaned
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        /*
        Calculate the binary string information, including the percentage of 0 and 1, and the total length of the binary string.
        */
        var zeroes: Int64 = 0
        var ones: Int64 = 0

        for (bit in this.binary_string) {
            if (bit == '0') {
                zeroes += 1
            } else if (bit == '1') {
                ones += 1
            }
        }

        let bitLength = zeroes + ones
        var info = HashMap<String, Float64>()
        if (bitLength == 0) {
            info.add("Zeroes", 0.0)
            info.add("Ones", 0.0)
        } else {
            info.add("Zeroes", Float64(zeroes) / Float64(bitLength))
            info.add("Ones", Float64(ones) / Float64(bitLength))
        }
        info.add("Bit length", Float64(bitLength))
        return info
    }

    public func convert_to_ascii(): String {
        /*
        Convert the binary string to an ASCII string.
        */
        var result = ""
        var value: Int64 = 0
        var bitCount: Int64 = 0

        for (bit in this.binary_string) {
            value = value * 2
            if (bit == '1') {
                value += 1
            }
            bitCount += 1

            if (bitCount == 8) {
                result = result + Rune(UInt32(value)).toString()
                value = 0
                bitCount = 0
            }
        }
        return result
    }

    public func convert_to_utf8(): String {
        /*
        Convert the binary string to a UTF-8 string.
        */
        var bytes = ArrayList<Int64>()
        var value: Int64 = 0
        var bitCount: Int64 = 0

        for (bit in this.binary_string) {
            value = value * 2
            if (bit == '1') {
                value += 1
            }
            bitCount += 1

            if (bitCount == 8) {
                bytes.add(value)
                value = 0
                bitCount = 0
            }
        }

        var result = ""
        var index: Int64 = 0
        while (index < bytes.size) {
            let first = bytes[index]
            var codePoint: Int64 = 0
            var sequenceLength: Int64 = 0

            if (first <= 0x7F) {
                codePoint = first
                sequenceLength = 1
            } else if (first >= 0xC2 && first <= 0xDF) {
                codePoint = first - 0xC0
                sequenceLength = 2
            } else if (first >= 0xE0 && first <= 0xEF) {
                codePoint = first - 0xE0
                sequenceLength = 3
            } else if (first >= 0xF0 && first <= 0xF4) {
                codePoint = first - 0xF0
                sequenceLength = 4
            } else {
                result = result + Rune(0xFFFD).toString()
                index += 1
                continue
            }

            if (index + sequenceLength > bytes.size) {
                result = result + Rune(0xFFFD).toString()
                break
            }

            var valid = true
            var offset: Int64 = 1
            while (offset < sequenceLength) {
                let next = bytes[index + offset]
                if (next < 0x80 || next > 0xBF) {
                    valid = false
                    break
                }
                codePoint = codePoint * 64 + (next - 0x80)
                offset += 1
            }

            if (valid) {
                if ((sequenceLength == 3 && codePoint < 0x800) ||
                    (sequenceLength == 4 && codePoint < 0x10000) ||
                    (codePoint >= 0xD800 && codePoint <= 0xDFFF) ||
                    codePoint > 0x10FFFF) {
                    valid = false
                }
            }

            if (valid) {
                result = result + Rune(UInt32(codePoint)).toString()
                index += sequenceLength
            } else {
                result = result + Rune(0xFFFD).toString()
                index += 1
            }
        }

        return result
    }
