        let now = DateTime.now()
        var count: Int64 = 0

        while (count < num_events) {
            var bestIndex: Int64 = -1

            var index: Int64 = 0
            while (index < events.size) {
                let event = events[index]
                if (!selected[index] && event.start_time >= now) {
                    if (bestIndex < 0 ||
                        event.start_time < events[bestIndex].start_time) {
                        bestIndex = index
                    }
                }
                index += 1
            }

            if (bestIndex < 0) {
                return result
            }

            selected[bestIndex] = true
            result.add(events[bestIndex])
            count += 1
        }

        return result
    }
